PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS todo_items (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, notes TEXT, is_completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS calendar_items (id INTEGER PRIMARY KEY AUTOINCREMENT, item_date TEXT NOT NULL, title TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_calendar_items_item_date ON calendar_items(item_date);

CREATE TABLE IF NOT EXISTS investment_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, account_type TEXT NOT NULL DEFAULT 'brokerage', institution TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS investment_stocks (id INTEGER PRIMARY KEY AUTOINCREMENT, ticker TEXT NOT NULL, company_name TEXT, shares REAL NOT NULL DEFAULT 0, cost_basis REAL NOT NULL DEFAULT 0, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, purchase_date TEXT, purchase_price REAL NOT NULL DEFAULT 0, target_sell_price REAL NOT NULL DEFAULT 0, market_price REAL, dividend_yield REAL, market_updated_at TEXT);
CREATE TABLE IF NOT EXISTS investment_mutual_funds (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, fund_name TEXT, shares REAL NOT NULL DEFAULT 0, cost_basis REAL NOT NULL DEFAULT 0, expense_ratio REAL, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, purchase_date TEXT, purchase_price REAL NOT NULL DEFAULT 0, market_price REAL, dividend_yield REAL, market_updated_at TEXT);
CREATE TABLE IF NOT EXISTS investment_stock_watchlist (id INTEGER PRIMARY KEY AUTOINCREMENT, ticker TEXT NOT NULL, company_name TEXT, target_buy_price REAL NOT NULL DEFAULT 0, market_price REAL, dividend_yield REAL, market_updated_at TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS investment_mutual_fund_watchlist (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, fund_name TEXT, target_buy_price REAL NOT NULL DEFAULT 0, market_price REAL, dividend_yield REAL, market_updated_at TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS investment_banking_products (id INTEGER PRIMARY KEY AUTOINCREMENT, institution TEXT NOT NULL, product_name TEXT NOT NULL, principal REAL NOT NULL DEFAULT 0, interest_rate REAL, maturity_date TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, open_date TEXT, maturity_value REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS investment_collectibles (id INTEGER PRIMARY KEY AUTOINCREMENT, item_name TEXT NOT NULL, category TEXT, purchase_price REAL, estimated_value REAL, condition TEXT, storage_location TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, target_price REAL NOT NULL DEFAULT 0, quantity INTEGER NOT NULL DEFAULT 1, purchase_link TEXT);
CREATE TABLE IF NOT EXISTS investment_pipeline (id INTEGER PRIMARY KEY AUTOINCREMENT, idea_name TEXT NOT NULL, category TEXT, target_amount REAL, target_date TEXT, status TEXT NOT NULL DEFAULT 'researching', notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, investment_type TEXT NOT NULL DEFAULT 'Stock', desired_purchase_price REAL NOT NULL DEFAULT 0, desired_shares REAL NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS recipes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT, servings INTEGER NOT NULL DEFAULT 0, prep_minutes INTEGER NOT NULL DEFAULT 0, cook_minutes INTEGER NOT NULL DEFAULT 0, ingredients TEXT, instructions TEXT, notes TEXT, image_data BLOB, image_name TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recipe_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wishlist_items (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT, estimated_price REAL NOT NULL DEFAULT 0, quantity INTEGER NOT NULL DEFAULT 1, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS travel_destinations (id INTEGER PRIMARY KEY AUTOINCREMENT, country TEXT, city TEXT, priority TEXT NOT NULL DEFAULT 'Medium', target_season TEXT, target_year INTEGER NOT NULL DEFAULT 0, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, make TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', vehicle_year INTEGER, vin TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicle_maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, title TEXT NOT NULL, due_date TEXT NOT NULL DEFAULT '', video_url TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicle_wishlist (id INTEGER PRIMARY KEY AUTOINCREMENT, vehicle_id INTEGER NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, item_name TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', estimated_price REAL NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS house_reminders (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, reminder_type TEXT NOT NULL DEFAULT '', due_date TEXT NOT NULL DEFAULT '', amount REAL NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS house_maintenance (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, frequency TEXT NOT NULL DEFAULT '', due_date TEXT NOT NULL DEFAULT '', video_url TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS house_improvements (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, priority TEXT NOT NULL DEFAULT '', estimated_cost REAL NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_price_history (symbol TEXT NOT NULL, price_date TEXT NOT NULL, close_price REAL NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(symbol, price_date));
